head.script:
/*  */
(function() {
    var uri = window.location.toString();
    if (/[?&]m=[01]/i.test(uri)) {
        var clean_uri = uri.replace(/[?&]m=[01]/gi, '');
        if (clean_uri.endsWith('?')) {
            clean_uri = clean_uri.slice(0, -1);
        }
        window.history.replaceState({}, document.title, clean_uri);
    }
})();
/*  */

