/* Menyembunyikan elemen dan widget bawaan Blogger secara mutlak agar tidak mengacaukan landing page */
#blogger-default-section, 
.main-inner, 
.blog-posts, 
.status-msg-wrap, 
.no-posts,
.feed-links {
    display: none !important;
    height: 0 !important;
    visibility: hidden !important;
    opacity: 0 !important;
}

body.script:
/*  */

// Fungsi Toggle untuk Drawer Sidebar Menu (Berlaku Desktop dan HP)
function toggleMenu() {
    const drawer = document.getElementById('sideDrawer');
    const overlay = document.getElementById('drawerOverlay');

    if (drawer.classList.contains('translate-x-full')) {
        // Tampilkan Drawer
        drawer.classList.remove('translate-x-full');
        overlay.classList.remove('hidden');
        setTimeout(() => { overlay.classList.add('opacity-100'); }, 10);
    } else {
        // Sembunyikan Drawer
        drawer.classList.add('translate-x-full');
        overlay.classList.remove('opacity-100');
        setTimeout(() => { overlay.classList.add('hidden'); }, 300);
    }
}

// Animasi Scroll Reveal untuk Kartu Peraturan (IntersectionObserver dengan staggered delay)
(function() {
    var revealEls = document.querySelectorAll('.reveal');
    if (!('IntersectionObserver' in window)) {
        revealEls.forEach(function(el) { el.classList.add('revealed'); });
        return;
    }
    var observer = new IntersectionObserver(function(entries) {
        entries.forEach(function(entry, i) {
            if (entry.isIntersecting) {
                var el = entry.target;
                var index = Array.prototype.indexOf.call(revealEls, el);
                setTimeout(function() {
                    el.classList.add('revealed');
                }, (index % 4) * 80);
                observer.unobserve(el);
            }
        });
    }, { threshold: 0.12, rootMargin: '0px 0px -40px 0px' });
    revealEls.forEach(function(el) { observer.observe(el); });
})();

// ===== GALERI LIGHTBOX =====
var galleryPhotos = [
    { src: "https://images.unsplash.com/photo-1558981403-c5f9899a28bc?q=80&w=1200&auto=format&fit=crop", caption: "Kopdar Mingguan Wacana Style" },
    { src: "https://images.unsplash.com/photo-1558980664-10e717b3ff0d?q=80&w=800&auto=format&fit=crop", caption: "Touring Senja" },
    { src: "https://images.unsplash.com/photo-1568772585407-9361f9bf3a87?q=80&w=800&auto=format&fit=crop", caption: "Ngopi Bareng" },
    { src: "https://images.unsplash.com/photo-1525160354320-d8e92641c563?q=80&w=800&auto=format&fit=crop", caption: "Barisan Motor" },
    { src: "https://images.unsplash.com/photo-1558980395-be2a5fc71c40?q=80&w=800&auto=format&fit=crop", caption: "Aspal Malam" },
