    { src: "https://images.unsplash.com/photo-1482951164281-2c9a11d5a712?q=80&w=800&auto=format&fit=crop", caption: "Kopdar Sore" },
    { src: "https://images.unsplash.com/photo-1558618666-fcd25c85cd64?q=80&w=800&auto=format&fit=crop", caption: "Sampai Jumpa" }
];
var lbIndex = 0;

function openLightbox(index) {
    lbIndex = index;
    updateLightbox();
    document.getElementById('lightbox').classList.add('open');
    document.body.style.overflow = 'hidden';
}

function closeLightbox() {
    document.getElementById('lightbox').classList.remove('open');
    document.body.style.overflow = '';
}

function changePhoto(dir) {
    lbIndex = (lbIndex + dir + galleryPhotos.length) % galleryPhotos.length;
    updateLightbox();
}

function updateLightbox() {
    var photo = galleryPhotos[lbIndex];
    document.getElementById('lbImage').src = photo.src;
    document.getElementById('lbImage').alt = photo.caption;
    document.getElementById('lbCaption').textContent = photo.caption;
    document.getElementById('lbCounter').textContent = (lbIndex + 1) + ' / ' + galleryPhotos.length;
}

// Navigasi keyboard: Esc untuk tutup, panah kiri/kanan untuk pindah foto
document.addEventListener('keydown', function(e) {
    var lb = document.getElementById('lightbox');
    if (lb.classList.contains('open')) {
        if (e.key === 'Escape') { closeLightbox(); }
        else if (e.key === 'ArrowLeft') { changePhoto(-1); }
        else if (e.key === 'ArrowRight') { changePhoto(1); }
    }
});

// Daftar Admin WhatsApp Wacana Style (format internasional tanpa +)
var waAdmins = [
    { nama: "Putra",  nomor: "6287814693521" },
    { nama: "Dafa",   nomor: "6289520273357" },
    { nama: "Arinta", nomor: "6283871992716" },
    { nama: "Indra",  nomor: "6288227908397" }
];

// Fungsi Submit Formulir Terkoneksi WhatsApp (kirim ke 4 Admin sekaligus)
function handleFormSubmit(event) {
    event.preventDefault();

    const nameInput = document.getElementById('riderName');
    const contactInput = document.getElementById('riderContact');
    const scooterInput = document.getElementById('scooterModel');
    const domisiliInput = document.getElementById('riderDomisili');
    const submitBtn = document.getElementById('submitBtn');
    const btnIcon = document.getElementById('btnIcon');
    const statusMessage = document.getElementById('statusMessage');
    const errorMessage = document.getElementById('errorMessage');

    const name = nameInput.value.trim();
    const contact = contactInput.value.trim();
    const scooter = scooterInput.value.trim();
    const domisili = domisiliInput.value.trim();

    if (name && contact && scooter && domisili) {
        // Loading State UI
        submitBtn.disabled = true;
        submitBtn.classList.add('opacity-75', 'cursor-not-allowed');
        btnIcon.className = "fa-solid fa-circle-notch animate-spin";
        statusMessage.classList.add('hidden');
        errorMessage.classList.add('hidden');

        // Mempersiapkan format pesan WhatsApp lengkap dengan data calon member
        var waMessage = "🚨 *WACANA STYLE - PENDAFTARAN BARU* 🚨\n\n" +
                        "👤 *Nama:* " + name + "\n" +
                        "📞 *Kontak HP:* " + contact + "\n" +
                        "🏍️ *Jenis Motor:* " + scooter + "\n" +
                        "📍 *Domisili:* " + domisili + "\n\n" +
                        "_Ayo segera proses dan hubungi calon anggota baru ini!_";

        // Encode pesan agar aman di URL wa.me
        var encodedMessage = encodeURIComponent(waMessage);

        // Buka WhatsApp ke semua admin secara bertahap agar tidak diblokir popup sekaligus
        waAdmins.forEach(function(admin, index) {
            setTimeout(function() {
                window.open(
                    "https://wa.me/" + admin.nomor + "?text=" + encodedMessage,
                    "_blank"
                );
            }, index * 700);
        });

        // Berhasil dikirim (notifikasi) - data dianggap terkirim karena membuka WA admin
        setTimeout(function() {
            statusMessage.classList.remove('hidden');

            // Tambahkan secara instan ke tampilan riwayat pendaftaran di bawah (Warna Merah)
            const list = document.getElementById('ridersList');
            const initial = name.charAt(0).toUpperCase();

            const riderDiv = document.createElement('div');
            riderDiv.className = "bg-zinc-900/60 border border-red-600/30 px-3 py-2.5 sm:px-4 sm:py-3 rounded-lg flex items-center gap-2 sm:gap-3 animate-pulse";
            riderDiv.innerHTML = `
                <div class="h-8 w-8 rounded-full bg-red-600 text-white flex items-center justify-center font-bold text-xs sm:text-sm">` + initial + `</div>
                <div>
                    <div class="text-xs font-bold text-white">` + name + `</div>
                    <div class="text-[9px] sm:text-[10px] text-gray-300">` + scooter + ` • ` + domisili + ` • ` + contact.substring(0, 4) + `-xxxx-xxxx</div>
                </div>
            `;
            list.insertBefore(riderDiv, list.firstChild);

            // Reset form input
            nameInput.value = '';
            contactInput.value = '';
            scooterInput.value = '';
            domisiliInput.value = '';

            setTimeout(function() {
                riderDiv.classList.remove('animate-pulse');
                riderDiv.style.borderColor = "rgb(39 39 42)";
            }, 3000);

            setTimeout(function() {
                statusMessage.classList.add('hidden');
            }, 8000);

            // Reset Button State
            submitBtn.disabled = false;
            submitBtn.classList.remove('opacity-75', 'cursor-not-allowed');
            btnIcon.className = "fa-solid fa-paper-plane";
        }, (waAdmins.length * 700) + 200);
    }
}
/*  */
